body.script:
const button = document.getElementById('fallback');
const target = 'https://michaelmb110b12-wq.github.io/macos-web/';
const frame = document.querySelector('iframe');

const openSite = () => window.location.href = target;
button.addEventListener('click', openSite);

let loaded = false;
frame.addEventListener('load', () => {
  loaded = true;
  button.hidden = true;
});

setTimeout(() => {
  if (!loaded) button.hidden = false;
}, 8000);
